// Patron simplificado de un agent
while (tarea no completada) {
    String observacion = llm.decide(herramientas, contexto);

    if (observacion.esAccion()) {
        Resultado r = herramientas.ejecutar(
            observacion.getTool(),
            observacion.getArgs()
        );
        contexto.agregar(r);
    } else {
        // El LLM decidio que la tarea esta completa
        return observacion.getRespuesta();
    }
}

