// Router: decidir que subagent usar
if (tarea.esLectura()) {
    delegarALector(tarea);
} else if (tarea.esEscritura()) {
    delegarAEscritor(tarea);
} else if (tarea.esDebug()) {
    delegarADebugger(tarea);
}

