// Ejemplo: la IA genera un "endpoint correcto"
@GetMapping("/api/users/{id}")
public User getUser(@PathVariable Long id) {
    return userRepository.findById(id)
        .orElseThrow(() -> new RuntimeException("Not found"));
}

// Bugs que la IA olvidó:
// 1. RuntimeException es demasiado generica (deberia ser NotFoundException)
// 2. No valida que id no sea null o negativo
// 3. No tiene rate limiting
// 4. No tiene cache
// 5. No maneja errores de conexion a la DB

// Version corregida con testing:
@GetMapping("/api/users/{id}")
public ResponseEntity<UserResponse> getUser(
        @PathVariable @Positive Long id) {
    return userRepository.findById(id)
        .map(user -> ResponseEntity.ok(toResponse(user)))
        .orElseGet(() -> ResponseEntity.notFound().build());
}

