// Edge cases tipicos que la IA olvida

// 1. Strings vacios y null
String nombre = "";  // la IA asume que siempre hay datos
if (nombre == null || nombre.isBlank()) {
    throw new IllegalArgumentException("Nombre requerido");
}

// 2. Listas vacias
List<String> items = List.of();  // la IA no prueba esto
items.stream().findFirst()  // Optional.empty()
    .orElseThrow();  // la IA lanza excepcion sin motivo

// 3. Limites numericos
int suma = Integer.MAX_VALUE + 1;  // overflow!
long grande = Long.MAX_VALUE;
float precise = 0.1f + 0.2f;  // != 0.3f

// 4. Concurrencia
Map<String, Integer> map = new HashMap<>();
// La IA usa HashMap en contexto concurrente
// Deberia ser ConcurrentHashMap

// 5. Recursos sin cerrar
FileInputStream fis = new FileInputStream("file.txt");
// La IA no cierra el stream
// Usar try-with-resources:
try (var fis = new FileInputStream("file.txt")) { ... }

